#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long power(long long base, long long exp) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

long long choose(long long n, long long k) {
    long long numerator = 1;
    long long denominator = 1;
    for (long long i = n - k + 1; i <= n; i++) {
        numerator = (numerator * i) % mod;
    }
    for (long long i = 1; i <= k; i++) {
        denominator = (denominator * i) % mod;
    }
    denominator = power(denominator, mod - 2);
    return (numerator * denominator) % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long kk;
    cin >> n >> kk;
    if (kk >= n) {
        cout << "0\n";
    } else {
        int k = (int)kk;
        int r = n - k;
        vector<long long> rChoose(r + 1);
        rChoose[0] = 1LL;
        long long numerator = 1LL;
        long long denominator = 1LL;
        for (int i = 1; i <= r; i++) {
            numerator = (numerator * (r + 1 - i)) % mod;
            denominator = (denominator * i) % mod;
            rChoose[i] = (numerator * power(denominator, mod - 2)) % mod;
        }
        long long answer = 0;
        long long sign = 1;
        for (int i = 0; i <= r; i++) {
            long long term = power((long long)(r - i), (long long)(n));
            answer = (answer + term * sign * rChoose[i]) % mod;
            sign = -sign;
        }
        answer = (answer * choose((long long)n, (long long)k)) % mod;
        if (k > 0) {
            answer = (answer * 2) % mod;
        }
        if (answer < 0) {
            answer += mod;
        }
        cout << answer << "\n";
    }
    return 0;
}
